"Images generated by a connected Aero Lab renderer, tied to one native field frame."
const VIEW_CAPTURE_LOCK=ReentrantLock()
const VIEW_CAPTURE_MAX_BYTES=16*1024^2
_view_capture_root(id)=joinpath(JOBS_ROOT,_id(id),"view_captures")
_view_capture_path(id,request)=joinpath(_view_capture_root(id),_id(request)*".json")
function _write_view_capture(path,value)
    mkpath(dirname(path));temporary=path*".tmp"
    open(temporary,"w") do io;JSON3.write(io,value);end
    mv(temporary,path;force=true)
end
function _view_frame_identity(id,url)
    prefix="/api/aero/jobs/$id/files/"
    startswith(url,prefix)&&endswith(url,".lbmw") || throw(ArgumentError("Choose a native wall-sample frame from this case"))
    parts=split(url[length(prefix)+1:end],'/';limit=2)
    length(parts)==2||throw(ArgumentError("Invalid native frame URL"))
    file=_case_file(id,parts[1],parts[2]);file===nothing&&throw(ArgumentError("Native frame is not available"))
    open(file,"r") do io
        read(io,8)==collect(codeunits("LBMWFLD\0"))||throw(ArgumentError("Invalid native wall frame"))
        ltoh(read(io,UInt32))==1||throw(ArgumentError("Unsupported native wall frame version"))
        ltoh(read(io,UInt32))==1||throw(ArgumentError("Unsupported native wall fields"))
        count=ltoh(read(io,UInt64));0<count<=100_000_000||throw(ArgumentError("Invalid native sample count"))
        geometry=String(read(io,64));occursin(r"^[a-f0-9]{64}$",geometry)||throw(ArgumentError("Invalid geometry identity"))
        step=ltoh(read(io,Int64));step>0||throw(ArgumentError("Initialization is not an evolved surface result"))
        filesize(file)==128+4count||throw(ArgumentError("Incomplete native wall frame"))
        Dict("source_url"=>url,"geometry_sha256"=>geometry,"frame_sha256"=>bytes2hex(open(sha256,file)),"step"=>step,"sample_count"=>count)
    end
end
function request_view_capture(id,req)
    _load_job(id);body=_body(req)
    identity=_view_frame_identity(id,String(get(body,"frame_url","")))
    field=String(get(body,"field","cp"));field in ("cp","pressure")||throw(ArgumentError("Choose pressure or Cp"))
    width=_integer(get(body,"width",1600),"width";lo=400,hi=3840)
    height=_integer(get(body,"height",1000),"height";lo=300,hi=2160)
    lock(VIEW_CAPTURE_LOCK) do
        root=_view_capture_root(id);mkpath(root)
        # One pending request per case prevents an unattended queue of GPU renders.
        for name in readdir(root)
            endswith(name,".json")||continue
            old=_plain(JSON3.read(read(joinpath(root,name),String)))
            get(old,"status","")=="pending"&&time()<old["expires_at"]&&
                throw(ArgumentError("A view capture is already waiting for Aero Lab"))
        end
        request=string(uuid4())
        data=merge(identity,Dict("request_id"=>request,"job_id"=>id,"status"=>"pending",
            "field"=>field,"representation"=>"wall_samples","width"=>width,"height"=>height,
            "created_utc"=>string(now(UTC)),"expires_at"=>time()+180))
        _write_view_capture(_view_capture_path(id,request),data)
        _response(202,data)
    end
end
function pending_view_capture(id,req=nothing)
    _load_job(id);root=_view_capture_root(id);isdir(root)||return _response(200,Dict("request"=>nothing))
    candidates=Any[]
    lock(VIEW_CAPTURE_LOCK) do
        if req!==nothing&&HTTP.header(req,"X-Aero-View-Client")=="viewport"
            _write_view_capture(joinpath(root,"browser.json"),Dict("status"=>"renderer_connected","last_seen_utc"=>string(now(UTC)),"last_seen_epoch"=>time()))
        end
        for name in readdir(root)
            endswith(name,".json")||continue
            data=_plain(JSON3.read(read(joinpath(root,name),String)))
            get(data,"status","")=="pending"&&time()<data["expires_at"]&&push!(candidates,data)
        end
    end
    _response(200,Dict("request"=>isempty(candidates) ? nothing : last(sort!(candidates;by=x->x["created_utc"]))))
end
function fail_view_capture(id,request,req)
    lock(VIEW_CAPTURE_LOCK) do
        path=_view_capture_path(id,request);isfile(path)||throw(ArgumentError("Unknown view capture request"))
        data=_plain(JSON3.read(read(path,String)));data["status"]=="pending"||throw(ArgumentError("View request is already closed"))
        message=String(get(_body(req),"error","Aero Lab could not render the requested view"))
        merge!(data,Dict("status"=>"error","error"=>first(message,2000),"completed_utc"=>string(now(UTC))))
        _write_view_capture(path,data);_response(200,data)
    end
end
function view_capture_status(id,request)
    path=_view_capture_path(id,request);isfile(path)||return _bad("View capture not found",404)
    data=_plain(JSON3.read(read(path,String)))
    get(data,"status","")=="pending"&&time()>=data["expires_at"]&&(data["status"]="expired")
    _response(200,data)
end
function accept_view_capture(id,request,req)
    lock(VIEW_CAPTURE_LOCK) do
        path=_view_capture_path(id,request);isfile(path)||throw(ArgumentError("Unknown view capture request"))
        data=_plain(JSON3.read(read(path,String)))
        data["status"]=="pending"&&time()<data["expires_at"]||throw(ArgumentError("View capture request expired or already completed"))
        for (header,key) in (("X-Aero-Step","step"),("X-Aero-Samples","sample_count"))
            tryparse(Int,HTTP.header(req,header))==data[key]||throw(ArgumentError("Rendered $key does not match the requested native frame"))
        end
        HTTP.header(req,"X-Aero-Geometry")==data["geometry_sha256"]||throw(ArgumentError("Rendered geometry does not match"))
        HTTP.header(req,"X-Aero-Frame")==data["frame_sha256"]||throw(ArgumentError("Rendered pressure frame does not match"))
        HTTP.header(req,"X-Aero-Representation")=="wall_samples"||throw(ArgumentError("View must show native wall samples"))
        HTTP.header(req,"X-Aero-Field")==data["field"]||throw(ArgumentError("Rendered quantity does not match"))
        _view_frame_identity(id,data["source_url"])==Dict(k=>data[k] for k in ("source_url","geometry_sha256","frame_sha256","step","sample_count"))||throw(ArgumentError("Native source changed while capturing"))
        bytes=req.body
        45<=length(bytes)<=VIEW_CAPTURE_MAX_BYTES||throw(ArgumentError("PNG image is empty or exceeds 16 MiB"))
        bytes[1:8]==UInt8[0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]||throw(ArgumentError("View capture must be PNG"))
        bytes[13:16]==collect(codeunits("IHDR"))&&bytes[end-7:end-4]==collect(codeunits("IEND"))||throw(ArgumentError("PNG image is incomplete"))
        be32(i)=sum(UInt32(bytes[i+j])<<(8*(3-j)) for j in 0:3)
        be32(17)==data["width"]&&be32(21)==data["height"]||throw(ArgumentError("PNG dimensions do not match the request"))
        png=joinpath(_view_capture_root(id),request*".png")
        open(png*".tmp","w") do io;write(io,bytes);end
        mv(png*".tmp",png;force=true)
        merge!(data,Dict("status"=>"complete","completed_utc"=>string(now(UTC)),
            "image_sha256"=>bytes2hex(sha256(bytes)),"image_bytes"=>length(bytes),
            "image_url"=>"/api/aero/jobs/$id/view-captures/$request/image",
            "image_path"=>png,"capture_kind"=>"Aero Lab Babylon viewport with field legend"))
        _write_view_capture(path,data);_response(200,data)
    end
end
function view_capture_image(id,request)
    path=_view_capture_path(id,request);isfile(path)||return _bad("View capture not found",404)
    data=_plain(JSON3.read(read(path,String)))
    get(data,"status","")=="complete"||return _bad("View is not captured yet",409)
    # The path is derived here, never accepted from uploaded JSON or an HTTP path.
    png=joinpath(_view_capture_root(id),_id(request)*".png")
    isfile(png)||return _bad("View image not found",404)
    HTTP.Response(200,["Content-Type"=>"image/png","Cache-Control"=>"no-store"],read(png))
end
